import {summonPool} from './summon-catalog.mjs';
import {receiveSummon} from './summon-ledger.mjs';
import {reserveStories} from './legendary-stories.mjs';
import {REGIONS,RATES,SHINY_RATE,summonRoll,isShiny} from './model.mjs';
import {icon,drawPortrait,preload,loadImage} from './art.mjs';
import {drawSummonScene} from './summon-scene.mjs';
export class Summoning {
 constructor(game){this.g=game;this.gen=1;this.busy=false;this.presentationOpen=false}
 rank(rarity){return Math.max(1,RATES.findIndex(r=>r.key===rarity)+1)}
 hasStory(result){const id=parseInt(result.key);return !!result.story&&!this.attemptedStories?.has(id)&&this.g.state.legendaryStories.pending.some(p=>p.id===id)}
 begin(){
  if(this.presentationOpen)return;this.presentationOpen=true;this.previousMusic=this.g.audio.music.scene;this.g.audio.music.unlock();this.g.audio.music.setScene('invocation');document.body.classList.add('summoning-active');
  this.abort=new AbortController();document.addEventListener('keydown',e=>{if(e.code==='Escape'&&this.busy&&this.g.modal.classList.contains('summon-dialog')){e.preventDefault();this.skip()}},{signal:this.abort.signal});
  if(!document.fullscreenElement&&document.documentElement.requestFullscreen){try{document.documentElement.requestFullscreen().then(()=>{this.ownsFullscreen=true;if(!this.presentationOpen)this.releaseFullscreen()}).catch(()=>{})}catch{}}
 }
 releaseFullscreen(){if(this.ownsFullscreen&&document.fullscreenElement===document.documentElement)document.exitFullscreen?.().catch(()=>{});this.ownsFullscreen=false}
 chrome(index,count,skip=false){return `<header class="summon-header"><div><span>PORTAIL ${REGIONS[this.gen-1].toUpperCase()}</span><b>${this.phase==='summary'?`RÉCAPITULATIF · ${count} INVOCATIONS`:count>1?`INVOCATION ${index+1} / ${count}`:'UNE NOUVELLE RENCONTRE'}</b></div><div><button data-act="toggle-music" data-music-icon aria-label="Musique de l’invocation">♫</button>${skip?'<button data-act="summon-skip" class="summon-skip-control">Passer l’invocation →</button>':''}</div></header>`}
 open(content,{index=0,count=1,locked=true,skip=false}={}){this.stopAnimation();this.g.openModal(`<section class="summon-stage" data-phase="${this.phase||'arrival'}" style="--summon-color:${this.color||'#a4d9f4'}"><canvas class="summon-landscape" width="640" height="360" aria-hidden="true"></canvas><div class="summon-shade"></div>${this.chrome(index,count,skip)}<div class="summon-content">${content}</div></section>`,{locked,className:'summon-dialog',onClose:()=>this.cleanup()})}
 stars(rarity,shiny=false){return `<div class="summon-rarity ${rarity}"><span class="summon-stars" aria-label="${this.rank(rarity)} étoiles">${'★'.repeat(this.rank(rarity))}</span><b>${this.g.rarity(rarity).name}</b>${shiny?'<span class="summon-shiny-mark">✧ CHROMATIQUE</span>':''}</div>`}
 wait(ms){return new Promise(resolve=>{let timer;const done=()=>{clearTimeout(timer);if(this.wake===done)this.wake=null;resolve()};this.wake=done;timer=setTimeout(done,ms)})}
 async invoke(count=1){
  const g=this.g;if(this.busy||!g.requireStarter())return;if(count!==1&&count!==10)return;if(g.state.tickets<count)return g.toast(`Il te faut ${count} ticket${count>1?'s':''} universel${count>1?'s':''}.`);
  this.busy=true;this.skipRequested=false;this.attemptedStories=new Set();this.stopAnimation();this.begin();
  const results=Array.from({length:count},()=>summonRoll(g.dex,this.gen));reserveStories(g.state,results);for(const r of results)receiveSummon(g.state,r);g.state.tickets-=count;g.state.history=[...results.slice().reverse(),...g.state.history].slice(0,30);g.save();g.cinema.preload(results);preload(results.map(r=>r.key));this.batch=results;
  try{
   await this.ceremony(results);
   for(let i=0;i<results.length;i++){
    await this.reveal(results[i],i,count);
    if(count>1&&!this.skipRequested)await new Promise(resolve=>this.advance=resolve);
   }
   if(count>1)this.summary(results);else if(this.skipRequested)this.result(results[0],0,1);
  }catch(error){this.summary(results);g.toast('Tes Pokémon sont sauvegardés. Voici les résultats.');console.error(error)}
  finally{this.busy=false;this.advance=null;this.wake=null}
 }
 async ceremony(results){
  const best=results.reduce((a,b)=>this.rank(a.rarity)>=this.rank(b.rarity)?a:b),reduced=this.g.state.settings.reducedMotion;this.color=this.g.rarity(best.rarity).color;this.sceneRank=this.rank(best.rarity);this.phase='opening';
  this.open(`<div class="summon-ceremony"><span class="eyebrow">${results.length===10?'DIX RENCONTRES T’ATTENDENT':'LE CERCLE RÉPOND À TON APPEL'}</span><div class="summon-orb" aria-hidden="true"><i></i><span>◒</span></div><h2 data-summon-message>Le portail s’ouvre…</h2>${this.stars(best.rarity)}<p>${results.length>1?'La lumière annonce la plus haute rareté de ce tirage.':'Une présence approche dans la lumière.'}</p><div class="summon-steps"><i class="active"></i><i></i><i></i></div><small>Les nouvelles rencontres légendaires seront jouées même si tu passes.</small></div>`,{count:results.length,skip:true});this.animateCanvas(null,null);
  for(const [phase,label,ms] of [['opening','Le portail s’ouvre…',650],['charge',`Une présence ${best.rarity==='legendary'?'légendaire':best.rarity==='epic'?'épique':best.rarity==='rare'?'rare':'se précise'}…`,900],['arrival','Les étoiles s’alignent…',750]]){
   if(this.skipRequested)break;this.phase=phase;const root=this.g.modal.querySelector('.summon-stage');if(root)root.dataset.phase=phase;const message=this.g.modal.querySelector('[data-summon-message]');if(message)message.textContent=label;this.g.modal.querySelectorAll('.summon-steps i').forEach((e,i)=>e.classList.toggle('active',i<=['opening','charge','arrival'].indexOf(phase)));await this.wait(reduced?30:ms);
  }
 }
 stopAnimation(){cancelAnimationFrame(this.revealFrame);this.revealFrame=0}
 cleanup(){this.stopAnimation();this.wake?.();this.next();this.abort?.abort();document.body.classList.remove('summoning-active');this.g.modal.classList.remove('summon-dialog');this.g.modal.style.removeProperty('--summon-color');if(this.presentationOpen){this.presentationOpen=false;this.g.audio.music.setScene(this.previousMusic||this.g.page);this.releaseFullscreen()}if(this.g.page==='gacha')this.g.render()}
 next(){const advance=this.advance;this.advance=null;advance?.()}
 skip(){if(!this.busy)return;this.skipRequested=true;this.wake?.();this.next()}
 animateCanvas(canvas,key){
  this.stopAnimation();const scene=this.g.modal.querySelector('.summon-landscape'),start=performance.now();let last=0;
  const animate=now=>{if(!this.g.modal.open||!scene?.isConnected)return;this.revealFrame=requestAnimationFrame(animate);if(document.hidden||now-last<32)return;last=now;const t=this.g.state.settings.reducedMotion?0:(now-start)/1000;drawSummonScene(scene.getContext('2d'),t,{color:this.color,rank:this.sceneRank,reduced:this.g.state.settings.reducedMotion,phase:this.phase});
   if(canvas?.isConnected){const x=canvas.getContext('2d');x.clearRect(0,0,canvas.width,canvas.height);drawPortrait(x,key,canvas.width/2,canvas.height*.49,canvas.height*.86,'Idle',0,t)}
   if(!canvas)for(const c of this.g.modal.querySelectorAll('canvas[data-result-key]')){const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);drawPortrait(x,c.dataset.resultKey,c.width/2,c.height/2,100,'Idle',0,t)}
  };animate(performance.now());
 }
 async playStory(result){
  if(!this.hasStory(result))return;this.attemptedStories.add(parseInt(result.key));this.stopAnimation();await this.g.cinema.play(result);
 }
 async reveal(result,index,count){
  const g=this.g;this.begin();this.attemptedStories||=new Set();this.color=g.rarity(result.rarity).color;this.sceneRank=this.rank(result.rarity);this.phase='arrival';
  if(!this.skipRequested){
   const image=loadImage(icon(result.key));if(!image.complete)await Promise.race([new Promise(resolve=>{image.addEventListener('load',resolve,{once:true});image.addEventListener('error',resolve,{once:true})}),this.wait(1000)]);
   if(!this.skipRequested){this.open(`<div class="invocation-sequence silhouette-sequence"><span class="eyebrow">${count>1?`RENCONTRE ${index+1} / ${count}`:'UNE SILHOUETTE SE DESSINE'}</span><div class="silhouette-halo"></div><div class="silhouette-frame"><canvas class="silhouette-mon" width="300" height="250" aria-label="Silhouette du Pokémon à découvrir"></canvas></div>${this.stars(result.rarity)}<h2>Qui répond à ton appel ?</h2>${isShiny(result.key)?'<p class="shiny-omen">✧ Une lumière chromatique scintille…</p>':'<p>Les hautes herbes frémissent…</p>'}</div>`,{index,count,skip:true});this.animateCanvas(g.modal.querySelector('.silhouette-mon'),result.key);await this.wait(g.state.settings.reducedMotion?50:1150)}
  }
  // Passing ordinary reveals never bypasses a reserved first legendary encounter.
  await this.playStory(result);
  if(!this.skipRequested)this.result(result,index,count);
 }
 result(result,index,count){
  const g=this.g;this.color=g.rarity(result.rarity).color;this.sceneRank=this.rank(result.rarity);this.phase='reward';g.audio.chime(result.rarity);
  this.open(`<div class="invocation-result rarity-reveal ${result.rarity} ${isShiny(result.key)?'is-shiny':''}" style="--summon-color:${this.color}"><div class="reveal-rays"></div><span class="eyebrow">${count>1?`INVOCATION ${index+1} / ${count}`:result.duplicate?'UN VISAGE FAMILIER':'UNE NOUVELLE ALLIANCE'}</span>${this.stars(result.rarity,isShiny(result.key))}<canvas class="reveal-mon colored-arrival" width="300" height="250" aria-label="${g.escape(g.poke(result.key).name)}"></canvas><h2>${g.poke(result.key).name}</h2>${!result.duplicate?'<span class="new-badge">NOUVEAU !</span>':''}<p>${result.duplicate?(isShiny(result.key)?'Exemplaire chromatique conservé.':`Doublon converti en ${result.fragments} poussières d’étoiles.`):'A rejoint ta collection.'}</p><p class="summon-ivs">IV : ${(result.iv||[]).join(' / ')}${result.ivUpgrades?' · '+result.ivUpgrades+' IV amélioré(s)':''}</p>${isShiny(result.key)?'<p class="shiny-note">✧ Variante chromatique · 1 % de chance</p>':''}<div class="summon-reward-actions">${count>1?`<button class="primary" data-act="summon-next">${index===count-1?'Voir le récapitulatif':'Suivant · '+(index+2)+' / '+count} →</button><button data-act="summon-skip">Passer l’invocation</button>`:`<button class="primary" data-act="close-modal">Accueillir ${g.poke(result.key).name}</button><button data-act="summon-again" ${g.state.tickets<1?'disabled':''}>Invoquer à nouveau · 1 ticket</button>`}</div></div>`,{index,count,locked:count>1});g.modal.style.setProperty('--summon-color',this.color);this.animateCanvas(g.modal.querySelector('.reveal-mon'),result.key);
 }
 summary(results){
  const g=this.g;this.phase='summary';const best=results.reduce((a,b)=>this.rank(a.rarity)>=this.rank(b.rarity)?a:b);this.color=g.rarity(best.rarity).color;this.sceneRank=this.rank(best.rarity);const fragments=results.reduce((n,r)=>n+(r.fragments||0),0),newCount=results.filter(r=>!r.duplicate).length;
  this.open(`<div class="multi-summary"><span class="eyebrow">LE CERCLE A RÉPONDU À TON APPEL</span><h2>Tes ${results.length} invocation${results.length>1?'s':''}</h2><p>${newCount} nouveau${newCount>1?'x':''} compagnon${newCount>1?'s':''}${fragments?' · +'+fragments+' poussières d’étoiles':''}</p>${this.pendingMarkup()}<div class="multi-results">${results.map((r,i)=>`<article class="multi-result ${r.rarity} ${isShiny(r.key)?'multi-shiny':''}" style="--summon-color:${g.rarity(r.rarity).color}"><small>${String(i+1).padStart(2,'0')} · ${g.rarity(r.rarity).name}${isShiny(r.key)?' · ✧ CHROMATIQUE':''}</small><span class="result-stars">${'★'.repeat(this.rank(r.rarity))}</span><canvas width="130" height="110" data-result-key="${r.key}" aria-label="${g.escape(g.poke(r.key).name)}"></canvas><b>${g.poke(r.key).name}</b><span>${r.duplicate?(isShiny(r.key)?'Chromatique conservé':'+'+r.fragments+' poussières d’étoiles'):'NOUVEAU !'}${r.ivUpgrades?' · '+r.ivUpgrades+' IV ↑':''}</span></article>`).join('')}</div><div class="multi-summary-actions"><button class="primary" data-act="close-modal">Accueillir mes Pokémon</button><button data-act="summon-again-ten" ${g.state.tickets<10?'disabled':''}>Invoquer ×10 · 10 tickets</button></div></div>`,{count:results.length,locked:false});g.modal.style.setProperty('--summon-color',this.color);this.animateCanvas(null,null);
 }
 pendingMarkup(){const pending=this.g.state.legendaryStories.pending.filter(p=>this.g.dex[p.id]&&this.g.state.roster.includes(p.key));return pending.length?`<section class="legendary-pending"><div><b>Une légende t’attend</b><p>${pending.length} rencontre${pending.length>1?'s':''} à découvrir.</p></div><button data-act="legendary-pending">Voir la rencontre →</button></section>`:''}
 async resumePending(){if(this.busy)return;const p=this.g.state.legendaryStories.pending.find(p=>this.g.dex[p.id]&&this.g.state.roster.includes(p.key));if(!p)return;this.g.closeModal(true);this.busy=true;this.skipRequested=false;this.attemptedStories=new Set();this.begin();const result={...p,rarity:'legendary',story:true,duplicate:false,fragments:0};try{await this.playStory(result);this.result(result,0,1)}finally{this.busy=false}}
 render(){const g=this.g,featured=[150,249,384,487,643,716,800,888,1007][this.gen-1];return `${g.heading('LES PORTAILS DE LA TOUR','Le cercle d’invocation','Premières formes et Pokémon sans évolution. Un seul ticket pour les neuf régions.')}<div class="ticket-explainer"><div class="ticket-glyph"></div><div><strong>${g.state.tickets} tickets universels</strong><p>1 ticket = 1 invocation, dans le portail de ton choix.</p></div><button data-act="route" data-page="survival">Gagner des tickets ↗</button></div>${this.pendingMarkup()}<div class="region-tabs">${REGIONS.map((r,i)=>`<button class="${i+1===this.gen?'selected':''}" data-act="portal" data-gen="${i+1}"><small>GÉN. ${i+1}</small>${r}</button>`).join('')}</div><section class="summon-showcase"><div class="portal-visual"><div class="portal-ring"></div><div class="portal-ring ring-two"></div><img class="portal-featured" src="${icon(String(featured))}" alt="${g.poke(featured).name}"><span class="portal-rune">✦</span></div><div class="portal-copy"><span class="eyebrow">PORTAIL ${REGIONS[this.gen-1].toUpperCase()}</span><h2>Les échos de<br>${REGIONS[this.gen-1]}</h2><p>Recrute la première forme de chaque lignée, puis fais-la évoluer en jouant. Les lignées épiques gardent leur rareté dès leur première forme.</p><span class="shiny-note">✧ Shiny : 1 % · en plus de la rareté</span><button class="primary summon-button" data-act="summon" ${g.state.tickets<1||!g.state.starter?'disabled':''}><span class="ticket-mark">▱</span> Invoquer un Pokémon <small>1 ticket universel</small></button><button class="summon-button summon-ten" data-act="summon-ten" ${g.state.tickets<10||!g.state.starter?'disabled':''}>Invoquer ×10 <small>10 tickets universels</small></button><p class="multi-rates-note">10 tirages indépendants · mêmes taux · aucun bonus garanti</p><div class="portal-actions"><button class="text-button" data-act="rates">Voir tous les Pokémon et leurs taux →</button></div></div></section><section class="rates-panel"><div class="section-title"><h2>Les taux du portail</h2><span>Identiques sur les 9 portails</span></div><div class="rates-grid">${RATES.map(r=>`<div class="rate ${r.key}"><span>◆ ${r.name}</span><strong>${r.rate}<small>%</small></strong><i style="--rate:${r.rate}%;--rarity:${r.color}"></i></div>`).join('')}</div><p>IV indépendants entre 0 et 31. Doublons normaux : 25 / 75 / 200 / 600 poussières selon la rareté. Chaque IV conserve sa meilleure valeur. Les exemplaires shiny sont conservés. Le shiny est tiré séparément avec une probabilité de 1 % : il conserve la rareté du Pokémon. Les légendaires incluent les fabuleux. Les variantes disponibles et leurs taux individuels figurent dans le détail.</p></section><div class="summon-bottom"><section class="panel"><h3>Comment obtenir des tickets ?</h3><div class="earning-row"><span>✦</span><div><b>Survis dans les terres de cendre</b><p>1 ticket toutes les 20 secondes de survie.</p></div></div><div class="earning-row"><span>♜</span><div><b>Triomphe d’un gardien</b><p>2 tickets pour chaque étage vaincu.</p></div></div></section><section class="panel"><h3>Dernières invocations</h3><div class="summon-history">${g.state.history.slice(0,6).map(r=>`<button class="history-mon ${r.rarity}" data-act="inspect" data-key="${r.key}"><img src="${icon(r.key)}" alt="${g.poke(r.key).name}"><span>${g.poke(r.key).name}${isShiny(r.key)?' ✧':''}</span></button>`).join('')||'<p class="muted">Le cercle attend ta première invocation.</p>'}</div></section></div>`}
 rates(){const g=this.g,pool=summonPool(g.dex,this.gen);g.openModal(`<span class="eyebrow">TRANSPARENCE DES INVOCATIONS</span><h2>Portail ${REGIONS[this.gen-1]}</h2><p>Seules les premières formes et les espèces sans pré-évolution sont invocables. Les lignées épiques gardent leur rareté dès leur première forme. Le taux total inclut la variante normale et la variante shiny. Le tirage shiny indépendant à 1 % utilise uniquement les espèces disposant d’une variante PMD vérifiée.</p><div class="all-rates">${RATES.map(r=>{const mons=pool.filter(p=>p.rarity===r.key),rate=r.rate/mons.length;return `<details><summary><span class="${r.key}">◆ ${r.name}</span><b>${r.rate} % · ${mons.length} espèces</b></summary><div class="rates-list">${mons.map(p=>`<div><span>${p.name}</span><b>${((r.rate*.99/mons.length)+(p.shiny!==false?r.rate*.01/Math.max(1,mons.filter(p=>p.shiny!==false).length):0)).toFixed(5)} %</b><small>dont shiny ${p.shiny!==false?(r.rate*.01/Math.max(1,mons.filter(p=>p.shiny!==false).length)).toFixed(6)+' %':'indisponible'}</small></div>`).join('')}</div></details>`}).join('')}</div>`)}
}
